--
-- Table structure for table `series`
--

DROP TABLE IF EXISTS `series`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `series` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `analyte_name_original` varchar(245) CHARACTER SET utf8 DEFAULT NULL,
  `fk_analyzed_chemical_id` int(11) DEFAULT NULL,
  `figure_name` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `figure_series_identifier` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `author_comment` varchar(2000) CHARACTER SET utf8 DEFAULT NULL,
  `time_units_original` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `conc_units_original` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `conc_units_normalized` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `log_concentration_values` tinyint(4) DEFAULT NULL,
  `loq` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `loq_units` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `analytical_method_detail` varchar(64) CHARACTER SET utf8 DEFAULT NULL,
  `n_subjects_in_series` int(11) DEFAULT NULL COMMENT 'when authors report a range, the lower value has been captured',
  `fk_subject_id` int(11) DEFAULT NULL,
  `conc_medium_original` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `conc_medium_normalized` varchar(50) CHARACTER SET utf8 DEFAULT NULL,
  `curator_comment` varchar(216) CHARACTER SET utf8 DEFAULT NULL,
  `fk_study_id` int(11) DEFAULT NULL,
  `radiolabeled` tinyint(4) DEFAULT NULL,
  `analyte_dtxsid` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `analyte_casrn` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `test_substance_dtxsid` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `test_substance_casrn` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL,
  `fk_test_chemical_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_figures_2_idx` (`fk_subject_id`),
  KEY `fk_series_1_idx` (`fk_study_id`),
  CONSTRAINT `fk_series_1` FOREIGN KEY (`fk_study_id`) REFERENCES `studies` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_series_2` FOREIGN KEY (`fk_subject_id`) REFERENCES `subjects` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=32412 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

