CREATE TABLE `studies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fk_reference_document_id` int(11) DEFAULT NULL,
  `fk_extraction_document_id` int(11) DEFAULT NULL,
  `fk_dosed_chemical_id` int(11) DEFAULT NULL,
  `test_substance_name_original` varchar(245) CHARACTER SET utf8 DEFAULT NULL,
  `dose_level_normalized` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dose_level_original` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `dose_level_original_units` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `administration_route_original` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `administration_route_normalized` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dose_duration` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dose_frequency` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dose_vehicle` varchar(144) COLLATE utf8_unicode_ci DEFAULT NULL,
  `dose_volume` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `fasting_period` varchar(245) COLLATE utf8_unicode_ci DEFAULT NULL,
  `curator_comment` varchar(245) CHARACTER SET utf8 DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_studies_1_idx` (`fk_reference_document_id`),
  KEY `fk_studies_2_idx` (`fk_extraction_document_id`),
  CONSTRAINT `fk_studies_1` FOREIGN KEY (`fk_reference_document_id`) REFERENCES `documents` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_studies_2` FOREIGN KEY (`fk_extraction_document_id`) REFERENCES `documents` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=1931 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
