CREATE TABLE `subjects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `species` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `sex` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `age` varchar(45) CHARACTER SET utf8 DEFAULT NULL,
  `age_category` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'category thresholds described in Sayre CvT publication. when no numeric age given, reported descriptors are used',
