  `subtype` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `height` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `weight` varchar(200) COLLATE utf8_unicode_ci DEFAULT NULL,
  `weight_kg` double DEFAULT NULL,
  `weight_estimated` tinyint(4) DEFAULT NULL COMMENT '0: weight_kg listed as reported (possibly with unit conversion), 1: mean weight of other species, subtype, sex subjects, 2: mean of weight range reported',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=41252 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
