--
-- Table structure for table `tk_parameters`
--

DROP TABLE IF EXISTS `tk_parameters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tk_parameters` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `fk_series_id` int(11) DEFAULT NULL,
  `fk_study_id` int(11) DEFAULT NULL,
  `fk_chemical_id` int(11) DEFAULT NULL,
  `calculated_with_invivopkfit` tinyint(4) DEFAULT NULL,
  `parameter_name` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `parameter_unit` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `parameter_value` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `parameter_value_sd` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `calculation_date` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `comment` varchar(245) COLLATE utf8_unicode_ci DEFAULT NULL,
  `joint_analysis_studies` varchar(64) CHARACTER SET utf8 DEFAULT NULL,
  `reason_for_omittal` varchar(45) COLLATE utf8_unicode_ci DEFAULT NULL,
  `loglikelihood` float DEFAULT NULL,
  `AIC` float DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_tk_parameters_1_idx` (`fk_series_id`),
  KEY `fk_tk_parameters_2_idx` (`fk_study_id`),
  KEY `fk_tk_parameters_3_idx` (`fk_chemical_id`),
  CONSTRAINT `fk_tk_parameters_1` FOREIGN KEY (`fk_series_id`) REFERENCES `series` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_tk_parameters_2` FOREIGN KEY (`fk_study_id`) REFERENCES `studies` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_tk_parameters_3` FOREIGN KEY (`fk_chemical_id`) REFERENCES `chemicals` (`id`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=8010 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

